[
  {
    "vulnerability": "SQL injection",
    "function": "do_login",
    "severity": "HIGH",
    "reason": "User-supplied 'user' and 'pw' values are interpolated directly into the SQL query via an f-string, allowing an attacker to bypass authentication or extract arbitrary data (e.g., ' OR '1'='1)."
  },
  {
    "vulnerability": "Reflected Cross-Site Scripting (XSS)",
    "function": "do_reflect",
    "severity": "MEDIUM",
    "reason": "The 'name' query-parameter value is embedded into the HTML response without any encoding or sanitization, enabling injection of arbitrary client-side script."
  },
  {
    "vulnerability": "OS Command Injection",
    "function": "do_ping",
    "severity": "HIGH",
    "reason": "The 'host' value is concatenated directly into a shell command string (ping -c 1 {host}), so shell metacharacters in the input can inject and execute arbitrary commands."
  },
  {
    "vulnerability": "Information Disclosure",
    "function": "do_login",
    "severity": "MEDIUM",
    "reason": "On a SQL error the handler returns the full query text and database error message to the client, leaking schema details and aiding further exploitation."
  },
  {
    "vulnerability": "Excessive Data Exposure in Response",
    "function": "do_login",
    "severity": "MEDIUM",
    "reason": "A successful (or SQLi-bypassed) login returns the entire row including the 'secret' column, exposing sensitive credentials/session tokens to the caller."
  }
]
